  const gastoCombAnt = parseFloat(d.total_gasto_comb_ant || 0);
  const litros = parseFloat(d.total_litros || 0);
  const litrosAnt = parseFloat(d.total_litros_ant || 0);
  const veic = parseInt(d.qtd_veiculos_ativos || 0, 10);
  const veicAnt = parseInt(d.qtd_veiculos_ativos_ant || 0, 10);
  const kmFilial = parseFloat(d.total_km_calculado || 0);
  const kmFilialAnt = parseFloat(d.total_km_ant || 0);
  const custoKmFilial = parseFloat(d.custo_km_comb_medido || 0);

  sumGastoComb += gastoComb; sumGastoCombAnt += gastoCombAnt;
  sumLitros += litros; sumLitrosAnt += litrosAnt;
  sumKm += kmFilial; sumKmAnt += kmFilialAnt;
  sumVeiculos += veic; sumVeiculosAnt += veicAnt;

  filiaisList.push({ nome: nomeFilial, gastoComb, litros, veic, custoKmFilial });

  const postos = Array.isArray(d.postos_utilizados) ? d.postos_utilizados : [];
  for (const p of postos) {
    const pKey = (p.posto || 'Posto') + ' | ' + (p.cidade || '') + ' | ' + (p.combustivel || '');
    if (!postosMap[pKey]) {
      postosMap[pKey] = { posto: p.posto || 'Posto', cidade: p.cidade || 'N/D', uf: p.uf || 'N/D',
        combustivel: p.combustivel || 'Diesel', litros: 0, gasto: 0, preco_anp: parseFloat(p.preco_anp || 6.22) };
    }
    postosMap[pKey].litros += parseFloat(p.total_litros || 0);
    postosMap[pKey].gasto += parseFloat(p.total_gasto || 0);
  }
}

const precoMedioGeral = sumLitros > 0 ? (sumGastoComb / sumLitros) : 0;
const precoMedioAntGeral = sumLitrosAnt > 0 ? (sumGastoCombAnt / sumLitrosAnt) : 0;
const custoKmCombGeral = sumKm > 0 ? (sumGastoComb / sumKm) : null;
